{
  "summary": "Fresh read-back confirms the original transfer is cancelled with no funds held. Correct the payee, fund USD via the quoted EUR-to-USD conversion, retry the USD transfer, and defer the queued payout to preserve the USD reserve.",
  "moves": [
    {
      "kind": "defer_payout",
      "payoutId": "queued_marketing_7000"
    },
    {
      "kind": "correct_beneficiary",
      "beneficiaryId": "9a45987e-cffc-4f0a-81d7-[digits]",
      "companyName": "Northwind Steel Fabrication LLC",
      "accountName": "Northwind Steel Fabrication LLC"
    },
    {
      "kind": "fx_conversion",
      "buyCurrency": "USD",
      "sellCurrency": "EUR",
      "buyAmount": 28000
    },
    {
      "kind": "retry_transfer",
      "amount": 40000,
      "currency": "USD",
      "beneficiaryId": "9a45987e-cffc-4f0a-81d7-[digits]"
    }
  ]
}

{
  "objections": [
    {
      "check": "missing_retry_transfer",
      "severity": "block",
      "detail": "Original transfer 43217eec-6053-4fe6-b760-[digits] is CANCELLED with pending 0 and reserved 0, so it holds no money. correct_beneficiary only updates the payee; it does not create a new Airwallex transfer. No retry_transfer move is filed, so the executor will not reissue the 40,000 USD payment."
    },
    {
      "check": "funding_gap_for_retry",
      "severity": "note",
      "detail": "If the canceled 40,000 USD transfer is to be retried, no fx_conversion move is proposed. USD available is 22,000 and the reserve floor is 10,000, so at least 28,000 USD must be sourced externally; if the deferred 7,000 USD marketing payout remains a ledger hold, the 28,000 USD quote would still leave a 7,000 USD shortfall."
    },
    {
      "check": "deferral_release_condition",
      "severity": "note",
      "detail": "The deferral of queued_marketing_7000 is released only 'after supplier settles'. Since the supplier transfer is CANCELLED and no retry is proposed in this move set, ensure there is a verifiable settlement event; otherwise the marketing retainer could remain deferred indefinitely."
    },
    {
      "check": "quote_expiry",
      "severity": "note",
      "detail": "Quote f27afcd8-ea2c-43ed-bb5d-f43010e07eb0 is valid only until 2026-11-02T14:15:00+0000. If an fx_conversion is added, it must be executed before that time."
    }
  ]
}
